# Lanternhold v132: Support tasks server part. Paste into AWS CloudShell (us-east-1). Needs John's go; run with the v132 release.
# Creates Lambda lanternhold-support (from infra/lambda/support.js) and two routes with the usual sign-in check:
# GET /support, POST /support/claim. Players link a Discord or itch.io account; the Lambda asks Discord / itch.io who the sign-in
# belongs to and pays the Sigils at once. Touches no existing Lambda. Safe to run twice.
set -e
R=us-east-1; API=nyu3u8gc73; ACC=$(aws sts get-caller-identity --query Account --output text)
mkdir -p ~/lhv132/support && cd ~/lhv132
WT=$(aws dynamodb describe-table --table-name lanternhold-wallets --query Table.TableArn --output text)
HT=$(aws dynamodb describe-table --table-name lanternhold-heroes --query Table.TableArn --output text)
TT=$(aws dynamodb describe-table --table-name lanternhold-trade --query Table.TableArn --output text)
# 1. code
echo  | base64 -d > support/index.js
(cd support && zip -qj ../support.zip index.js)
# 2. role: read heroes, add Sigils to wallets, claim rows in the trade table
TRUST='{"Version":"2012-10-17","Statement":[{"Effect":"Allow","Principal":{"Service":"lambda.amazonaws.com"},"Action":"sts:AssumeRole"}]}'
aws iam get-role --role-name lanternhold-support-role >/dev/null 2>&1 || aws iam create-role --role-name lanternhold-support-role --assume-role-policy-document "$TRUST" >/dev/null
aws iam attach-role-policy --role-name lanternhold-support-role --policy-arn arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole
aws iam put-role-policy --role-name lanternhold-support-role --policy-name support-tables --policy-document "{\"Version\":\"2012-10-17\",\"Statement\":[{\"Effect\":\"Allow\",\"Action\":[\"dynamodb:GetItem\"],\"Resource\":\"$HT\"},{\"Effect\":\"Allow\",\"Action\":[\"dynamodb:GetItem\",\"dynamodb:UpdateItem\"],\"Resource\":\"$WT\"},{\"Effect\":\"Allow\",\"Action\":[\"dynamodb:GetItem\",\"dynamodb:Query\",\"dynamodb:PutItem\",\"dynamodb:UpdateItem\",\"dynamodb:DeleteItem\"],\"Resource\":\"$TT\"}]}"
echo "waiting 15 s for the role"; sleep 15
# 3. the Lambda
if aws lambda get-function --function-name lanternhold-support >/dev/null 2>&1; then
  aws lambda update-function-code --function-name lanternhold-support --zip-file fileb://support.zip >/dev/null
else
  aws lambda create-function --function-name lanternhold-support --runtime nodejs22.x --handler index.handler --memory-size 128 --timeout 10 \
    --role arn:aws:iam::$ACC:role/lanternhold-support-role --environment "Variables={WALLETS=lanternhold-wallets,HEROES=lanternhold-heroes,TRADE=lanternhold-trade}" --zip-file fileb://support.zip >/dev/null
fi
aws lambda wait function-updated --function-name lanternhold-support
aws lambda update-function-configuration --function-name lanternhold-support --environment "Variables={WALLETS=lanternhold-wallets,HEROES=lanternhold-heroes,TRADE=lanternhold-trade}" >/dev/null
aws lambda wait function-updated --function-name lanternhold-support
# 4. routes, with the same sign-in check as GET /boss
AUTH=$(aws apigatewayv2 get-routes --api-id $API --query "Items[?RouteKey=='GET /boss'].AuthorizerId" --output text)
ARN=arn:aws:lambda:$R:$ACC:function:lanternhold-support
INT=$(aws apigatewayv2 get-integrations --api-id $API --query "Items[?IntegrationUri=='$ARN'].IntegrationId" --output text)
[ -z "$INT" ] && INT=$(aws apigatewayv2 create-integration --api-id $API --integration-type AWS_PROXY --integration-uri $ARN --payload-format-version 2.0 --query IntegrationId --output text)
aws lambda add-permission --function-name lanternhold-support --statement-id apigw-support --action lambda:InvokeFunction --principal apigateway.amazonaws.com \
  --source-arn "arn:aws:execute-api:$R:$ACC:$API/*/*/*" >/dev/null 2>&1 || true
for K in "GET /support" "POST /support/claim"; do
  [ -z "$(aws apigatewayv2 get-routes --api-id $API --query "Items[?RouteKey=='$K'].RouteId" --output text)" ] && \
    aws apigatewayv2 create-route --api-id $API --route-key "$K" --authorization-type JWT --authorizer-id "$AUTH" --target "integrations/$INT" >/dev/null
done
# 5. smoke test: must say 401 (no sign-in)
curl -s -o /dev/null -w "support %{http_code}\n" "https://$API.execute-api.$R.amazonaws.com/support"
echo "done. Undo: delete the two routes, the integration, Lambda lanternhold-support and role lanternhold-support-role."
